from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import refund_shipping
from ledgerly.errors import BillingError
from ledgerly.models import Payment

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(status="captured", amt="100.00"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# partial then full
p=mk(); refund_shipping(p,Decimal("30.00"),T0); assert p.refunded_amount==Decimal("30.00") and p.status=="captured"
refund_shipping(p,Decimal("70.00"),T0); assert p.refunded_amount==Decimal("100.00") and p.status=="refunded"
print("partial/full ok")

# over refund
p=mk()
try: refund_shipping(p,Decimal("100.01"),T0); print("FAIL")
except BillingError as e: print("over:",e.code)

# non-positive
for a in [Decimal("0"),Decimal("-1")]:
    try: refund_shipping(mk(),a,T0); print("FAIL")
    except BillingError as e: print("nonpos:",e.code)

# invalid state
try: refund_shipping(mk("authorized"),Decimal("1"),T0); print("FAIL")
except BillingError as e: print("state:",e.code)

# approval
try: refund_shipping(mk(),Decimal("600"),T0); print("FAIL")
except BillingError as e: print("approval:",e.code)
p=mk(); refund_shipping(p,Decimal("600"),T0,approved_by="mgr"); print("approved ok",p.refunded_amount)

# idempotency
audit.clear(); p=mk()
refund_shipping(p,Decimal("10"),T0,idempotency_key="k1")
refund_shipping(p,Decimal("10"),T0,idempotency_key="k1")
assert p.refunded_amount==Decimal("10.00"); print("idempotent ok")

# naive datetime
try: refund_shipping(mk(),Decimal("1"),datetime(2026,1,1)); print("FAIL")
except BillingError as e: print("naive:",e.code)
EOF"}

